$paths = @('data/verified_targets_queue.json', 'website/data/verified_targets_queue.json')
$utf8NoBom = New-Object System.Text.UTF8Encoding $false

foreach ($p in $paths) {
  $resolved = (Resolve-Path $p).Path
  $existing = Get-Content $resolved -Raw | ConvertFrom-Json
  $existingIds = @($existing | ForEach-Object { $_.id })
  $toAdd = @($newTargets | Where-Object { $existingIds -notcontains $_.id })
  $combined = @($existing) + $toAdd
  $jsonStr = $combined | ConvertTo-Json -Depth 10
  [System.IO.File]::WriteAllText($resolved, $jsonStr, $utf8NoBom)
  Write-Host "Updated $p : Existing $($existing.Count) + Added $($toAdd.Count) = Total $($combined.Count)"
}
